def lattice_coords(coords):
    # returns set of lattice points spanning [min,max] via gcd of differences
    import math
    s=set(); mn,mx=min(coords),max(coords)
    if len(set(coords))==1: return {mn}
    gs=[abs(a-b) for a,b in zip(sorted(coords[:-1]),sorted(coords[1:]))]
    g=__import__('math').gcd(*gs)
    return {mn+k*g for k in range(0,(mx-mn)//g+1)}
